const paths={grid:'M3 3h7v7H3z M14 3h7v7h-7z M3 14h7v7H3z M14 14h7v7h-7z',users:'M16 21v-2a4 4 0 0 0-4-4H6a4 4 0 0 0-4 4v2 M16 3a4 4 0 0 1 0 8 M22 21v-2a4 4 0 0 0-3-3.87 M13 7a4 4 0 1 1-8 0 4 4 0 0 1 8 0',check:'m5 12 4 4L19 6',circlecheck:'M22 11.1V12a10 10 0 1 1-5.9-9.1 M22 4 12 14l-3-3',clock:'M12 8v4l3 2 M22 12a10 10 0 1 1-20 0 10 10 0 0 1 20 0',bolt:'m13 2-9 12h7l-1 8 10-12h-7z',activity:'M3 12h4l3-8 4 16 3-8h4',settings:'M12 8a4 4 0 1 0 0 8 4 4 0 0 0 0-8 M9 3h6l1 3 3 1 2 5-2 5-3 1-1 3H9l-1-3-3-1-2-5 2-5 3-1z',chat:'M21 11.5a9 9 0 0 1-9 9 9 9 0 0 1-4-.9L3 21l1.4-4.8A9 9 0 1 1 21 11.5Z m-12-4 1 2-1 1c1 2 2 3 4 4l1-1 2 1v2c-4 1-9-4-9-7z',shield:'m12 3 8 3v6c0 5-8 9-8 9s-8-4-8-9V6z m-4 9 3 3 5-6',phone:'M8 2h8a2 2 0 0 1 2 2v16a2 2 0 0 1-2 2H8a2 2 0 0 1-2-2V4a2 2 0 0 1 2-2 M10 18h4 M10 5h4',refresh:'M20 7v5h-5 M4 17v-5h5 M6 7a7 7 0 0 1 11-2l3 3 M18 17a7 7 0 0 1-11 2l-3-3',arrow:'M5 12h14 m-5-5 5 5-5 5',plus:'M12 5v14 M5 12h14',download:'M12 3v12 m-5-5 5 5 5-5 M5 16v5h14v-5',search:'M10.5 18a7.5 7.5 0 1 0 0-15 7.5 7.5 0 0 0 0 15 M16 16l5 5',link:'m10 13 4-4 M8 16l-1 1a4 4 0 0 1-6-6l5-5a4 4 0 0 1 6 0 m0 2 1-1a4 4 0 0 1 6 6l-5 5a4 4 0 0 1-6 0',close:'m6 6 12 12 M6 18 18 6',info:'M12 11v6 M12 7h.01 M22 12a10 10 0 1 1-20 0 10 10 0 0 1 20 0',lock:'M5 10h14v11H5z M8 10V6a4 4 0 0 1 8 0v4',menu:'M4 6h16 M4 12h16 M4 18h16',pause:'M8 5v14 M16 5v14',play:'m8 4 12 8-12 8z',file:'M5 3h9l5 5v13H5z M14 3v6h5 M9 13h6 M9 17h6',help:'M9 9a3 3 0 1 1 5 2c-1 1-2 1-2 3 M12 17h.01 M22 12a10 10 0 1 1-20 0 10 10 0 0 1 20 0'};
const icon=(name,cls='')=>`<svg class="${cls}" viewBox="0 0 24 24" aria-hidden="true"><path d="${paths[name]||paths.info}"/></svg>`;
const esc=value=>String(value??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const num=n=>Number(n||0).toLocaleString();
const date=v=>v?new Date(v).toLocaleString('en-NG',{month:'short',day:'numeric',hour:'2-digit',minute:'2-digit'}):'—';
const names={overview:'Overview',groups:'Groups',approvals:'Approval jobs',activity:'Activity log',settings:'Settings'};
const navIcons={overview:'grid',groups:'users',approvals:'circlecheck',activity:'activity',settings:'settings'};
let page=location.hash.slice(1)||'overview', apiKey='', backend=localStorage.getItem('pro-approver-api')||location.origin, apiConnected=false, loading=false, filter='', statusFilter='all';
let state={connection:{state:'disconnected'},groups:[],jobs:[],activity:[],totals:{approved:0,failed:0}};
const selected=new Set();
let toastTimer;
function toast(message,error=false){const t=document.querySelector('#toast');t.textContent=message;t.className=error?'error':'';t.style.display='block';clearTimeout(toastTimer);toastTimer=setTimeout(()=>t.style.display='none',6000);}
async function api(path,body){if(!apiKey)throw new Error('Connect your VPS service first');const controller=new AbortController(),timer=setTimeout(()=>controller.abort(),90000);try{const response=await fetch(backend+path,{method:body===undefined?'GET':'POST',headers:{Authorization:`Bearer ${apiKey}`,...(body===undefined?{}:{'Content-Type':'application/json'})},body:body===undefined?undefined:JSON.stringify(body),signal:controller.signal,cache:'no-store',credentials:'omit'});const data=await response.json().catch(()=>({error:'The service did not return JSON. Check the API address.'}));if(!response.ok)throw new Error(data.error||`Request failed (${response.status})`);return data;}finally{clearTimeout(timer);}}
async function refresh(silent=false){if(loading||!apiKey)return;loading=true;try{state=await api('/api/state');apiConnected=true;render();if(!silent)toast('Dashboard refreshed');}catch(e){apiConnected=false;render();if(!silent)toast(e.message,true);}finally{loading=false;}}
function badge(status){const colors={connected:'green',completed:'green',running:'green',queued:'blue',paused:'amber',cancelled:'',logged_out:'red',disconnected:'',connecting:'amber',qr:'amber'};return `<span class="badge ${colors[status]||''}"><i></i>${esc(status.replaceAll('_',' '))}</span>`;}
function titleBlock(title,description,actions=''){return `<div class="page-heading"><div><span class="eyebrow">YOUR COMMUNITY, UNDER CONTROL</span><h1>${title}</h1><p>${description}</p></div><div class="heading-actions">${actions}</div></div>`;}
const primary=(label,action,ic='plus',disabled=false)=>`<button class="button primary" data-action="${action}" ${disabled?'disabled':''}>${icon(ic)}${label}</button>`;
const secondary=(label,action,ic='download')=>`<button class="button" data-action="${action}">${icon(ic)}${label}</button>`;
function stat(label,value,ic,sub,highlight=''){return `<div class="stat"><div class="stat-top">${label}<span class="stat-icon">${icon(ic)}</span></div><div class="stat-number">${value}</div><div class="stat-bottom">${highlight?`<span>${highlight}</span>`:''}${sub}</div></div>`;}
function empty(title,description,ic='users',action='connect',label='Connect WhatsApp',full=false){return `<div class="empty-state ${full?'empty-full':''}"><div class="empty-icon">${icon(ic)}</div><h3>${title}</h3><p>${description}</p>${primary(label,action,action==='connect'?'link':'plus')}</div>`;}
function overview(){const pending=state.groups.reduce((a,g)=>a+g.pending,0),autos=state.groups.filter(g=>g.auto_enabled).length;const online=apiConnected&&state.connection.state==='connected';return titleBlock('A little less admin. A lot more community.','Manage group requests, automate approvals, and keep things moving.',secondary('Export activity','export')+primary(online?'New approval job':'Connect WhatsApp',online?'new-job':'connect',online?'plus':'link'))+`${!online?`<div class="welcome-band"><span class="band-icon">${icon('chat')}</span><div><h3>Your groups. One place.</h3><p>Connect WhatsApp to see pending requests and start managing your groups.</p></div><button class="text-button" data-action="connect">Let’s get connected ${icon('arrow')}</button></div>`:''}<div class="stats">${stat('Managed groups',num(state.groups.length),'users',online?'Synced from your account':'Connect to sync your groups')}${stat('Pending requests',num(pending),'clock','Waiting for approval')}${stat('Approved requests',num(state.totals.approved),'circlecheck','Verified by WhatsApp')}${stat('Auto-approval',num(autos),'bolt',autos?'groups enabled':'No groups enabled',autos?'Active on':'')}</div><div class="dashboard-grid"><section class="panel"><div class="panel-header"><div><h3>Your groups</h3><p>A clear view of every community you manage.</p></div><button class="text-button" data-action="page:groups">View all ${icon('arrow')}</button></div>${state.groups.length?`<div class="group-list">${state.groups.slice(0,4).map(g=>`<div class="group-row"><span class="group-avatar">${icon('users')}</span><div class="group-info"><strong>${esc(g.name)}</strong><p>${num(g.member_count)} / ${num(g.capacity)} members · ${num(g.pending)} pending</p></div><button class="switch ${g.auto_enabled?'on':''}" data-action="group:${esc(g.id)}" aria-label="Configure ${esc(g.name)} auto approval"><span></span></button></div>`).join('')}</div>`:empty('Your communities will feel right at home.','Connect your WhatsApp account. Your groups and pending requests will appear here.')}<div class="panel-foot">${icon('shield')} Only groups where you’re an admin can approve requests.</div></section><section class="panel connection-card"><div class="card-label"><h3>WhatsApp connection</h3>${badge(online?'connected':'disconnected')}</div><div class="phone-wrap">${icon('phone')}<span class="phone-dot">${icon(online?'check':'link')}</span></div><h4>${online?esc(state.connection.account||'Account connected'):'Ready when you are.'}</h4><p>${online?'Your account is connected. Manage pairing and connection details here.':'Link your account with a QR code.<br>Your phone stays in your hands.'}</p>${secondary(online?'Manage connection':'Connect account','connect','link')}<div class="secure-note">${icon('lock')} Your session stays on your server.</div></section></div>${jobsPanel(state.jobs.slice(0,5),true)}<div class="below-note">${icon('info')}<span><strong>Automatic or historical?</strong> New requests run on autopilot. Existing requests stay yours to approve.</span><button class="text-button" data-action="guide">See how it works ${icon('arrow')}</button></div>`;}
function jobsPanel(jobs,compact=false){return `<section class="panel jobs-panel"><div class="panel-header"><div><h3>${compact?'Recent approval jobs':'Approval jobs'}</h3>${compact?'':'<p>Only verified approvals count toward your target.</p>'}</div>${compact?'<button class="text-button" data-action="page:approvals">View all '+icon('arrow')+'</button>':`<span class="badge">${jobs.length} jobs</span>`}</div><div class="table-wrap"><table><thead><tr><th>GROUP</th><th>APPROVAL TYPE</th><th>PROGRESS</th><th>STATUS</th><th>${compact?'CREATED':'ACTIONS'}</th></tr></thead><tbody>${jobs.map(j=>`<tr><td><strong>${esc(j.group_name)}</strong></td><td>${j.kind==='custom'?'Exact amount':j.kind==='auto'?'Automatic':'Approve all'}</td><td>${num(j.confirmed)} / ${num(j.target)}<div class="progress-track"><span style="width:${Math.min(100,100*j.confirmed/j.target)}%"></span></div></td><td>${badge(j.status)}${j.uncertain?` <span class="badge amber">${j.uncertain} uncertain</span>`:''}</td><td>${compact?date(j.created_at):`<div class="row-actions"><button data-action="job:${j.id}">Details</button>${['running','queued'].includes(j.status)?`<button data-action="control:${j.id}:pause">Pause</button>`:j.status==='paused'?`<button data-action="control:${j.id}:resume" ${j.uncertain?'disabled':''}>Resume</button>`:''}</div>`}</td></tr>`).join('')}</tbody></table></div>${jobs.length?'':`<div class="table-empty">${icon('file')}No approval jobs yet. Your first one starts here.</div>`}</section>`;}
function groupsPage(){let groups=state.groups.filter(g=>g.name.toLowerCase().includes(filter.toLowerCase()));return titleBlock('Every group. One clear view.','Sync your groups, manage automation, and choose what gets approved.',secondary('Sync groups','sync','refresh')+primary('Approve selected','selected-job','circlecheck',!selected.size))+`<div class="toolbar"><label class="search">${icon('search')}<input id="search" placeholder="Search groups…" value="${esc(filter)}" aria-label="Search groups"></label><span class="selection-note">${selected.size} selected</span></div><section class="panel"><div class="table-wrap"><table><thead><tr><th><input type="checkbox" id="select-all" aria-label="Select all admin groups" ${groups.filter(g=>g.is_admin).length&&groups.filter(g=>g.is_admin).every(g=>selected.has(g.id))?'checked':''}></th><th>GROUP</th><th>MEMBERS</th><th>PENDING</th><th>AUTO-APPROVAL</th><th>ACTIONS</th></tr></thead><tbody>${groups.map(g=>`<tr><td><input type="checkbox" class="select-group" value="${esc(g.id)}" ${selected.has(g.id)?'checked':''} ${!g.is_admin?'disabled':''} aria-label="Select ${esc(g.name)}"></td><td><div class="group-name"><span class="group-avatar">${icon('users')}</span><div><strong>${esc(g.name)}</strong><small>${g.is_admin?'You’re an admin':'Admin access required'}${g.error?` · ${esc(g.error)}`:''}</small></div></div></td><td>${num(g.member_count)} / ${num(g.capacity)}<div class="capacity-bar"><span style="width:${Math.min(100,100*g.member_count/g.capacity)}%"></span></div></td><td>${num(g.pending)}</td><td>${g.auto_enabled?'<span class="badge green"><i></i>Enabled</span>':'<span class="badge">Off</span>'}</td><td><div class="row-actions"><button data-action="group:${esc(g.id)}" ${!g.is_admin?'disabled':''}>Settings</button><button data-action="approve:${esc(g.id)}" ${!g.is_admin||!g.pending?'disabled':''}>Approve</button></div></td></tr>`).join('')}</tbody></table></div>${groups.length?'':empty(state.groups.length?'No matching groups':'No groups connected yet',state.groups.length?'Try another search.':'Pair your WhatsApp account, then sync your groups.','users','connect','Connect WhatsApp',true)}</section>`;}
function approvalsPage(){const jobs=state.jobs.filter(j=>statusFilter==='all'||j.status===statusFilter);return titleBlock('Give your queue a little momentum.','Approve an exact amount or work through the existing queue.',primary('New approval job','new-job','plus'))+`<div class="toolbar"><div class="filter-tabs">${['all','running','paused','completed'].map(v=>`<button class="filter-tab ${statusFilter===v?'active':''}" data-action="filter:${v}">${v[0].toUpperCase()+v.slice(1)}</button>`).join('')}</div><span class="tiny muted">${state.jobs.filter(j=>['queued','running'].includes(j.status)).length} active jobs</span></div>${jobsPanel(jobs)}<div class="below-note">${icon('shield')}Requests above your target stay pending. A full group pauses the job automatically.</div>`;}
function activityPage(){const logs=state.activity.filter(a=>`${a.event} ${a.detail} ${a.group_name}`.toLowerCase().includes(filter.toLowerCase()));return titleBlock('Every action, accounted for.','A record of connections, settings, jobs, and verified approvals.',secondary('Export CSV','export'))+`<div class="toolbar"><label class="search">${icon('search')}<input id="search" value="${esc(filter)}" placeholder="Search activity…" aria-label="Search activity"></label><span class="tiny muted">Latest 200 events</span></div><section class="panel"><div class="table-wrap"><table><thead><tr><th>TIME</th><th>LEVEL</th><th>GROUP</th><th>DETAILS</th></tr></thead><tbody>${logs.map(a=>`<tr><td>${date(a.at)}</td><td><span class="badge ${a.level==='error'?'red':a.level==='warn'?'amber':'green'}">${esc(a.level)}</span></td><td>${esc(a.group_name||'Workspace')}</td><td style="white-space:normal;min-width:250px">${esc(a.detail)}<div class="activity-event">${esc(a.event)}</div></td></tr>`).join('')}</tbody></table></div>${logs.length?'':`<div class="table-empty">${icon('activity')}No activity yet. Events will appear as you use the app.</div>`}</section>`;}
function settingsPage(){return titleBlock('Make it work your way.','Your connection, approval rules, and workspace controls.')+`<div class="settings-grid"><section class="panel"><div class="panel-header"><h3>Server connection</h3>${badge(apiConnected?'connected':'disconnected')}</div><div class="settings-body"><p>The dashboard connects to the persistent WhatsApp service on your VPS. Your admin key is kept in memory for this tab.</p><div class="field"><span>Service URL</span><input value="${esc(backend)}" readonly></div><div class="row-actions">${secondary('Configure connection','server','link')}${apiConnected?secondary('Lock dashboard','lock','lock'):''}</div></div></section><section class="panel"><div class="panel-header"><h3>WhatsApp account</h3>${badge(state.connection.state)}</div><div class="settings-body"><p>Pair with Linked devices in WhatsApp. Pairing credentials are stored in the VPS volume and restored after a restart.</p>${primary('Manage WhatsApp','connect','phone')}<p style="margin:16px 0 0;font-size:10px">To revoke access, unlink the device from WhatsApp → Linked devices.</p></div></section><section class="panel"><div class="panel-header"><h3>Approval rules</h3>${icon('shield')}</div><div class="settings-body"><div class="job-summary"><span>Maximum group capacity</span><strong>1,024 members</strong></div><div class="job-summary"><span>Custom target</span><strong>Verified approvals only</strong></div><div class="job-summary"><span>Existing requests</span><strong>Manual historical jobs</strong></div><div class="job-summary"><span>Ambiguous result</span><strong>Pause for review</strong></div><p style="margin-top:17px">Set a lower capacity and enable future auto-approval in each group’s settings.</p></div></section><section class="panel"><div class="panel-header"><h3>Session recovery</h3>${icon('refresh')}</div><div class="settings-body"><p>Connections retry automatically. If WhatsApp revokes or expires your session, clear the saved credentials and scan a new QR code.</p><div class="notice warn">Baileys is an unofficial WhatsApp client. WhatsApp may change compatibility or restrict linked accounts.</div><button class="button danger" data-action="reset-session" ${!apiConnected||state.connection.state==='connected'?'disabled':''}>Clear expired session</button></div></section></div>`;}
function render(){if(!names[page])page='overview';document.querySelector('#breadcrumb-title').textContent=names[page];document.querySelector('#nav').innerHTML=Object.entries(names).map(([key,label])=>`<button class="nav-item ${page===key?'active':''}" data-action="page:${key}">${icon(navIcons[key])}${label}</button>`).join('');document.querySelector('#content').innerHTML=({overview,groups:groupsPage,approvals:approvalsPage,activity:activityPage,settings:settingsPage}[page])();const online=apiConnected&&state.connection.state==='connected';const pill=document.querySelector('#connection-pill');pill.className='connection-pill '+(online?'online':'');pill.innerHTML=`<i></i>${online?'WhatsApp connected':apiConnected?'WhatsApp '+esc(state.connection.state.replaceAll('_',' ')):'Not connected'}`;document.querySelectorAll('[data-icon]').forEach(el=>el.innerHTML=icon(el.dataset.icon));bindFields();}
function showModal(title,body){document.querySelector('#modal-title').textContent=title;document.querySelector('#modal-content').innerHTML=body;if(!document.querySelector('#modal').open)document.querySelector('#modal').showModal();}
function closeModal(){document.querySelector('#modal').close();}
function serverModal(){showModal('Connect your server',`<p class="modal-description">Enter the HTTPS address of your VPS service and the admin key from its configuration.</p><form id="server-form"><label class="field">Service URL<input name="url" type="url" required value="${esc(backend)}" placeholder="https://approver.yourdomain.com" autocomplete="url"><small>Use the application’s public HTTPS address.</small></label><label class="field">Admin access key<input name="key" type="password" minlength="32" required placeholder="Enter your ADMIN_API_KEY" autocomplete="off"><small>Kept in this tab’s memory. You’ll enter it again after a reload.</small></label><div class="notice">The backend and Docker configuration are included in the source. Deploy the VPS service first, then connect it here.</div><p class="error-inline" id="form-error"></p><div class="dialog-actions"><button class="button" type="button" data-action="close">Cancel</button><button class="button primary" type="submit">Connect securely ${icon('arrow')}</button></div></form>`);document.querySelector('#server-form').onsubmit=async e=>{e.preventDefault();const form=new FormData(e.target);let url;try{url=new URL(form.get('url'));if(url.protocol!=='https:'&&!(url.protocol==='http:'&&['localhost','127.0.0.1'].includes(url.hostname)))throw new Error('Use an HTTPS URL');if(url.username||url.password||url.search||url.hash||url.pathname!=='/')throw new Error('Enter only the server origin, without a path or credentials');const old={backend,apiKey};backend=url.origin;apiKey=form.get('key');try{state=await api('/api/state');apiConnected=true;localStorage.setItem('pro-approver-api',backend);closeModal();render();toast('Server connected');connectionModal();}catch(error){backend=old.backend;apiKey=old.apiKey;throw error;}}catch(error){document.querySelector('#form-error').textContent=error.message==='Failed to fetch'?'Could not reach the server. Check its URL, TLS certificate, and allowed dashboard origin.':error.message;}};}
function connectionModal(){if(!apiConnected)return serverModal();const c=state.connection;showModal('Your WhatsApp connection',`${c.state==='connected'?`<div class="notice">${icon('circlecheck')} Connected as ${esc(c.account||'your WhatsApp account')}.</div><p class="modal-description">Your admin groups are ready to sync. To disconnect, unlink this device in WhatsApp.</p><div class="dialog-actions">${secondary('Sync groups','sync','refresh')}${primary('Done','close','check')}</div>`:`<p class="modal-description">Open WhatsApp on your phone and link this service as a companion device.</p>${c.qr?`<div class="qr-box"><img src="${c.qr}" alt="WhatsApp device pairing QR code"><p>Scan with WhatsApp → Linked devices → Link a device.</p></div>`:`<div class="qr-box"><div class="phone-wrap">${icon('phone')}</div><p>${c.state==='connecting'?'Requesting a QR code…':c.state==='logged_out'?'Your session was revoked. Clear it to pair again.':'Ready to pair your account.'}</p></div>`}<ol class="steps"><li>Open <strong>WhatsApp → Linked devices</strong>.</li><li>Choose <strong>Link a device</strong> and scan the QR.</li><li>Sync your groups and choose your approval rules.</li></ol><p class="tiny muted">Baileys is unofficial; account restrictions and compatibility changes are possible.</p><div class="dialog-actions">${c.state==='logged_out'?secondary('Clear expired session','reset-session','refresh'):primary(c.qr?'Refresh status':'Generate QR code',c.qr?'pair-refresh':'pair','link')}</div>`}`);}
async function groupModal(id){const g=state.groups.find(g=>g.id===id);if(!g)return;showModal('Group settings',`<p class="modal-description"><strong>${esc(g.name)}</strong> · ${num(g.member_count)} members · ${num(g.pending)} pending</p><form id="group-form"><label class="check-field"><input name="auto" type="checkbox" ${g.auto_enabled?'checked':''}>Automatically approve future join requests</label><div class="notice">Existing requests are synced before activation and stay in the historical queue. New requests are checked automatically while the VPS service runs.</div><label class="field">Member capacity<input name="capacity" type="number" min="1" max="1024" value="${g.capacity}" required><small>Approvals pause at this member count. Maximum: 1,024.</small></label><p class="error-inline" id="form-error"></p><div class="dialog-actions"><button class="button" type="button" data-action="close">Cancel</button><button class="button primary" type="submit">Save settings</button></div></form>`);document.querySelector('#group-form').onsubmit=async e=>{e.preventDefault();const f=new FormData(e.target);try{await api(`/api/groups/${encodeURIComponent(id)}/settings`,{auto_enabled:f.get('auto')==='on',capacity:Number(f.get('capacity'))});closeModal();await refresh(true);toast('Group settings saved');}catch(e){document.querySelector('#form-error').textContent=e.message;}};}
function newJob(ids=[]){if(!apiConnected)return serverModal();const eligible=state.groups.filter(g=>g.is_admin&&g.pending>0);if(!eligible.length){toast('No pending requests in an admin group. Sync your groups first.',true);return;}const options=ids.length?eligible.filter(g=>ids.includes(g.id)):eligible;if(!options.length)return;showModal(ids.length>1?'Approve selected groups':'New historical approval',`<p class="modal-description">Work through requests already waiting in your groups. Requests beyond your target stay pending.</p><form id="job-form">${ids.length>1?`<div class="notice">${options.map(g=>`${esc(g.name)} — ${num(g.pending)} pending`).join('<br>')}<br><strong>The chosen target applies to each group separately.</strong></div>`:`<label class="field">Group<select name="group">${options.map(g=>`<option value="${esc(g.id)}">${esc(g.name)} (${num(g.pending)} pending)</option>`).join('')}</select></label>`}<div class="mode-picker"><label class="mode-option"><input type="radio" name="kind" value="custom" checked><span>Exact amount<small>Stop at your chosen number of verified approvals.</small></span></label><label class="mode-option"><input type="radio" name="kind" value="all"><span>Approve all<small>Process the current queue until empty or full.</small></span></label></div><label class="field" id="amount-field">Approvals ${ids.length>1?'per group':''}<input name="amount" type="number" min="1" max="100000" value="${Math.min(100,...options.map(g=>g.pending))}" required></label><div class="notice">The worker rechecks admin rights and member capacity before each approval. A full group pauses its job.</div><p class="error-inline" id="form-error"></p><div class="dialog-actions"><button type="button" class="button" data-action="close">Cancel</button><button type="submit" class="button primary">Review approval ${icon('arrow')}</button></div></form>`);const form=document.querySelector('#job-form');form.onchange=()=>{document.querySelector('#amount-field').style.display=form.elements.kind.value==='custom'?'flex':'none';form.elements.amount.required=form.elements.kind.value==='custom';};form.onsubmit=e=>{e.preventDefault();const f=new FormData(form),kind=f.get('kind'),amount=Number(f.get('amount'));const groups=ids.length>1?options:[options.find(g=>g.id===f.get('group'))];if(kind==='custom'&&groups.some(g=>amount>g.pending)){document.querySelector('#form-error').textContent='The amount exceeds a selected group’s pending count.';return;}confirmJob(groups,kind,amount);};}
function confirmJob(groups,kind,amount){showModal('Review your approval job',`<p class="modal-description">This will approve real WhatsApp join requests for the following ${groups.length>1?'groups':'group'}.</p>${groups.map(g=>`<div class="job-summary"><span>${esc(g.name)}</span><strong>${kind==='all'?'All current requests':num(amount)+' approvals'}</strong></div><div class="job-summary muted"><span>Available member slots</span><span>${num(Math.max(0,g.capacity-g.member_count))}</span></div>`).join('')}<div class="notice" style="margin-top:18px">${kind==='all'?'Each job snapshots the current pending queue. Future requests are handled by your group’s auto-approval setting.':'Only confirmed approvals count toward the exact target. Remaining requests stay pending.'}</div><p class="error-inline" id="form-error"></p><div class="dialog-actions"><button class="button" data-action="close">Cancel</button><button class="button primary" id="confirm-job">${icon('circlecheck')}Start ${groups.length>1?'jobs':'approval'}</button></div>`);document.querySelector('#confirm-job').onclick=async e=>{const button=e.currentTarget;button.disabled=true;let started=0;try{for(const g of groups){await api('/api/jobs',{group_id:g.id,kind,amount});started++;}closeModal();page='approvals';location.hash=page;await refresh(true);toast(`${started} approval ${started===1?'job':'jobs'} queued`);}catch(e){document.querySelector('#form-error').textContent=`${started?`${started} job(s) started. `:''}${e.message}`;button.remove();await refresh(true);}};}
async function jobModal(id){const j=state.jobs.find(j=>j.id===id);if(!j)return;const result=await api(`/api/jobs/${id}/items`);const uncertain=result.items.filter(i=>['uncertain','sending'].includes(i.status));showModal('Approval job details',`<p class="modal-description"><strong>${esc(j.group_name)}</strong></p><div class="job-summary"><span>Status</span>${badge(j.status)}</div><div class="job-summary"><span>Confirmed approvals</span><strong>${num(j.confirmed)} / ${num(j.target)}</strong></div><div class="job-summary"><span>Created</span><span>${date(j.created_at)}</span></div>${j.reason?`<div class="notice warn" style="margin-top:16px">${esc(j.reason)}</div>`:''}${uncertain.length?`<h3 style="margin-top:22px">Review uncertain outcomes</h3><p class="tiny">Check each result in WhatsApp. Counting as approved also requires verified current membership. Skipping does not count it toward the target.</p>${uncertain.map(i=>`<div class="uncertain-item"><code>${esc(i.jid)}</code><div class="row-actions"><button data-action="reconcile:${id}:${encodeURIComponent(i.jid)}:approved">Count as approved</button><button data-action="reconcile:${id}:${encodeURIComponent(i.jid)}:pending">Still pending · retry</button><button data-action="reconcile:${id}:${encodeURIComponent(i.jid)}:skip">Skip</button></div></div>`).join('')}`:''}<div class="dialog-actions">${['running','queued','paused'].includes(j.status)?`<button class="button danger" data-action="cancel-job:${id}">Cancel job</button>`:''}${j.status==='paused'&&!uncertain.length?primary('Resume job',`control:${id}:resume`,'play'):secondary('Close','close','close')}</div>`);}
function guide(){showModal('A calmer way to manage requests',`<div class="notice">Two separate flows. One shared capacity check.</div><h3>Automatic approvals</h3><p>Enable this per group. The current queue is synced first, then only requests first seen after activation enter automatic jobs. Your VPS keeps working when the dashboard is closed.</p><h3>Historical approvals</h3><p>Choose Approve All to process a snapshot of the pending queue, or enter an exact number. Only a successful response plus verified membership counts. Anything above your target stays pending.</p><h3>Capacity and interruptions</h3><p>The worker checks the current member count before each approval, up to 1,024 or your lower limit. Disconnections trigger reconnection. Ambiguous approval results pause the job for your review.</p><div class="notice warn">Other admins can add members or handle requests at the same time. WhatsApp is the source of truth; the app never reports an unverified success.</div><div class="dialog-actions">${primary('Got it','close','check')}</div>`);}
function exportActivity(){if(!state.activity.length){toast('There is no activity to export yet');return;}const cell=v=>'"'+String(v??'').replace(/^[=+@-]/,"'$&").replaceAll('"','""')+'"';const rows=[['Time','Level','Event','Group','Details'],...state.activity.map(a=>[a.at,a.level,a.event,a.group_name,a.detail])];const url=URL.createObjectURL(new Blob(['\ufeff'+rows.map(r=>r.map(cell).join(',')).join('\r\n')],{type:'text/csv;charset=utf-8'}));const a=document.createElement('a');a.href=url;a.download='pro-whatsapp-activity.csv';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);}
function bindFields(){document.querySelector('#search')?.addEventListener('input',e=>{const pos=e.target.selectionStart;filter=e.target.value;render();const input=document.querySelector('#search');input.focus();input.setSelectionRange(pos,pos);});document.querySelectorAll('.select-group').forEach(input=>input.onchange=()=>{input.checked?selected.add(input.value):selected.delete(input.value);render();});const all=document.querySelector('#select-all');if(all)all.onchange=()=>{state.groups.filter(g=>g.is_admin&&g.name.toLowerCase().includes(filter.toLowerCase())).forEach(g=>all.checked?selected.add(g.id):selected.delete(g.id));render();};}
async function action(value){const [act,id,extra,outcome]=value.split(':');switch(act){case'page':page=id;filter='';location.hash=page;render();document.querySelector('.sidebar').classList.remove('open');break;case'connect':connectionModal();break;case'server':serverModal();break;case'close':closeModal();break;case'guide':guide();break;case'export':exportActivity();break;case'sync':await api('/api/sync',{});await refresh(true);if(document.querySelector('#modal').open)closeModal();toast('Groups synced');break;case'pair':await api('/api/connect',{});toast('Pairing requested. The QR code may take a few seconds.');await refresh(true);connectionModal();break;case'pair-refresh':await refresh(true);connectionModal();break;case'group':await groupModal(id);break;case'new-job':newJob();break;case'approve':newJob([id]);break;case'selected-job':newJob([...selected]);break;case'filter':statusFilter=id;render();break;case'job':await jobModal(id);break;case'control':await api(`/api/jobs/${id}/control`,{action:extra});closeModal();await refresh(true);toast(extra==='pause'?'Pause requested. An in-flight approval may finish.':'Job queued to resume');break;case'cancel-job':showModal('Cancel this approval job?',`<p class="modal-description">Confirmed approvals remain. No further requests will be started, but an approval already in flight may finish.</p><div class="dialog-actions"><button class="button" data-action="job:${id}">Go back</button><button class="button danger" data-action="confirm-cancel:${id}">Cancel job</button></div>`);break;case'confirm-cancel':await api(`/api/jobs/${id}/control`,{action:'cancel'});closeModal();await refresh(true);toast('Job cancelled');break;case'reconcile':await api(`/api/jobs/${id}/reconcile`,{jid:decodeURIComponent(extra),outcome});await refresh(true);await jobModal(id);toast('Outcome reviewed and recorded');break;case'reset-session':await api('/api/session/reset',{});await refresh(true);connectionModal();toast('Session cleared. Generate a new QR code.');break;case'lock':apiKey='';apiConnected=false;state={connection:{state:'disconnected'},groups:[],jobs:[],activity:[],totals:{approved:0,failed:0}};closeModal();render();toast('Dashboard locked');break;}}
document.addEventListener('click',async e=>{const button=e.target.closest('[data-action]');if(!button||button.disabled)return;button.disabled=true;try{await action(button.dataset.action);}catch(error){toast(error.message,true);}finally{if(button.isConnected)button.disabled=false;}});
document.querySelector('#close-modal').onclick=closeModal;
document.querySelector('#guide-button').onclick=guide;
document.querySelector('#menu-button').onclick=()=>document.querySelector('.sidebar').classList.toggle('open');
document.querySelector('#refresh-button').onclick=()=>apiKey?refresh():serverModal();
document.querySelector('#modal').addEventListener('click',e=>{if(e.target===document.querySelector('#modal')){const r=e.target.getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)closeModal();}});
window.addEventListener('hashchange',()=>{page=location.hash.slice(1)||'overview';render();});
render();
setInterval(async()=>{if(!apiKey||document.hidden)return;const old=state.connection;await refresh(true);if(document.querySelector('#modal').open&&document.querySelector('#modal-title').textContent==='Your WhatsApp connection'&&(old.state!==state.connection.state||old.qr!==state.connection.qr))connectionModal();},5000);
